const express = require('express');
const rateLimit = require('express-rate-limit');
const cloud = require('../cloudProvider');
const db = require('../db');

const app = express();
app.set('trust proxy', ['10.0.0.0/8']);

const restoreLimiter = rateLimit({
  windowMs: 60 * 60 * 1000,
  max: 2,
  keyGenerator: (req) => `restore_${req.user.id}`
});

app.post('/api/databases/:dbId/restore-snapshot', restoreLimiter, async (req, res) => {
  const { dbId } = req.params;
  const { snapshotId } = req.body;

  // Assert user is an admin of the tenant that owns the database instance
  const dbRecord = await db('managed_databases')
    .where({ id: dbId, tenant_id: req.user.tenantId })
    .first();

  if (!dbRecord || req.user.role !== 'dba_admin') {
    return res.status(403).json({ error: 'Forbidden: Insufficient permissions to restore database' });
  }

  await cloud.restoreDatabaseSnapshot(dbRecord.cloud_instance_id, snapshotId);

  return res.json({
    status: 'Restoring',
    databaseId: dbId,
    snapshotId
  });
});

module.exports = app;
